export const TEST_CENTRE_SLUGS = TEST_CENTRES.map((centre) => centre.slug);

const CENTRE_BY_SLUG = new Map(TEST_CENTRES.map((centre) => [centre.slug, centre]));

export const isValidTestCentre = (slug) => CENTRE_BY_SLUG.has(slug);

export const getTestCentre = (slug) => CENTRE_BY_SLUG.get(slug) ?? null;

/* Centres grouped by county slug — what the search page's county-then-centre
   filter renders, and what the profile wizard uses to narrow the picker. */
export const testCentresByCounty = () => {
  const grouped = {};
  for (const centre of TEST_CENTRES) {
    (grouped[centre.county] ||= []).push(centre);
  }
  return grouped;
};

export default TEST_CENTRES;
